                .arg(
                    Arg::new("tag")
                        .short('t')
                        .long("tag")
                        .value_name("tags")
                        .num_args(1..)
                        .action(ArgAction::Append)
                        .help("Set which tags the script belongs to."),
                )
                .arg(Arg::new("command").help("The command/script content to be executed.")),
        )
        .subcommand(
            Command::new("config-init")
                .alias("init")
                .about("alias: init - Add a config file."),
        )
        .subcommand(
            Command::new("copy")
                .alias("cp")
                .about("alias: cp - Copy existing alias to the new one")
                .arg(Arg::new("from-alias").required(true))
                .arg(Arg::new("to-alias").required(true)),
        )
        .subcommand(
            Command::new("edit")
                .about("Edit a script matching alias.")
                .arg(Arg::new("alias").required(true)),
        )
        .subcommand(
            Command::new("list")
                .alias("ls")
                .about("alias: ls - List scripts")
                .arg(
                    Arg::new("cmd_full")
                        .short('l')
                        .long("cmd_full")
                        .action(ArgAction::SetTrue)
                        .help("Display the full command."),
                )
                .arg(
                    Arg::new("list_aliases")
                        .short('q')
                        .long("list_aliases")
                        .action(ArgAction::SetTrue)
                        .help("Only displays aliases of the scripts."),
                )
                .arg(
                    Arg::new("cmd_width")
                        .short('c')
                        .long("cmd_width")
                        .value_name("cmd-width")
                        .value_parser(clap::value_parser!(usize))
                        .help("The max number of characters to display from the command."),
                )
                .arg(
                    Arg::new("tag")
                        .short('t')
                        .long("tag")
                        .value_name("tags")
