        );
    }

    let mut temp_file = tempfile::NamedTempFile::new().map_err(|e| e.to_string())?;
    use std::io::Write;
    temp_file
        .write_all(initial_content.as_bytes())
        .map_err(|e| e.to_string())?;

    let path = temp_file.path().to_path_buf();

    let status = std::process::Command::new(&editor)
        .arg(&path)
        .status()
        .map_err(|_| {
            format!(
                "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
                editor
            )
        })?;

    if !status.success() {
        return Err(format!(
            "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
            editor
        ));
    }

    let content = fs::read_to_string(&path).map_err(|e| e.to_string())?;
    Ok(content.trim_end_matches('\r').trim_end_matches('\n').to_string())
}

fn print_table(
    rows: &[(String, Script)],
    cmd_full: bool,
    cmd_width: Option<usize>,
    default_cmd_width: Option<usize>,
) {
    let mut alias_max = "Alias".len();
    let mut tags_max = "Tags".len();
    let mut cmd_max = "Command".len();
    let mut desc_max = "Description".len();

    let mut processed_rows = Vec::new();

    for (alias, script) in rows {
        let tags_str = match &script.tags {
            Some(t) if !t.is_empty() => t.join(","),
            _ => String::new(),
        };

        let raw_cmd = &script.command;
        let mut cmd_str = raw_cmd.clone();

        if !cmd_full {
            let width_limit = cmd_width.or(default_cmd_width).unwrap_or(80);
            if cmd_str.chars().count() > width_limit {
                cmd_str = cmd_str.chars().take(width_limit).collect();
            }
        }

        let desc_str = script.description.as_deref().unwrap_or("");

        alias_max = alias_max.max(alias.len());
        tags_max = tags_max.max(tags_str.len());
        cmd_max = cmd_max.max(cmd_str.len());
        desc_max = desc_max.max(desc_str.len());

        processed_rows.push((alias.clone(), tags_str, cmd_str, desc_str.to_string()));
    }

    let total_width = alias_max + tags_max + cmd_max + desc_max + 13;
    let border = "≖".repeat(total_width);

    println!("{}", border);
    println!(
        "⋮ {:<a_w$} ⋮ {:<t_w$} ⋮ {:<c_w$} ⋮ {:<d_w$} ⋮",
        "Alias",
        "Tags",
        "Command",
        "Description",
        a_w = alias_max,
        t_w = tags_max,
        c_w = cmd_max,
        d_w = desc_max
    );
    println!("{}", border);

    for (alias, tags, cmd, desc) in processed_rows {
        println!(
            "⋮ {:<a_w$} ⋮ {:<t_w$} ⋮ {:<c_w$} ⋮ {:<d_w$} ⋮",
            alias,
            tags,
            cmd,
            desc,
            a_w = alias_max,
            t_w = tags_max,
            c_w = cmd_max,
            d_w = desc_max
        );
    }
    println!("{}", border);
}

fn build_cli() -> Command {
    Command::new("pier")
        .version("0.1.6")
        .author("Benjamin Scholtz, Isak Johansson")
        .about("A simple script management CLI")
        .arg(
            Arg::new("config-file")
                .short('c')
                .long("config-file")
                .value_name("path")
                .help("Sets a custom config file.\n\nDEFAULT PATH is otherwise determined in this order:\n\n- $PIER_CONFIG_PATH (environment variable if set)\n\n- pier.toml (in the current directory)\n\n- $XDG_CONFIG_HOME/pier/config.toml\n\n- $XDG_CONFIG_HOME/pier/config\n\n- $XDG_CONFIG_HOME/pier.toml\n\n- $HOME/.pier.toml\n\n- $HOME/.pier\n\n [env: PIER_CONFIG_PATH=]"),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::SetTrue)
                .help("The level of verbosity"),
        )
        .arg(
            Arg::new("alias")
                .value_name("alias")
                .help("The alias or name for the script.")
                .required_unless_present_any(["config-init", "add", "list", "run", "show", "remove", "copy", "move", "edit"]),
        )
        .arg(
            Arg::new("args")
                .value_name("args")
                .num_args(0..)
                .help("The positional arguments to send to script."),
        )
        .subcommand(
            Command::new("add")
                .about("Add a new script to config.")
                .arg(
                    Arg::new("force")
                        .short('f')
                        .long("force")
                        .action(ArgAction::SetTrue)
                        .help("Allows to overwrite the existing script"),
                )
                .arg(
                    Arg::new("alias")
                        .short('a')
                        .long("alias")
                        .value_name("alias")
                        .required(true)
                        .help("The alias or name for the script."),
                )
                .arg(
                    Arg::new("description")
                        .short('d')
                        .long("description")
                        .value_name("description")
                        .help("The description for the script."),
                )
                .arg(
                    Arg::new("tag")
                        .short('t')
                        .long("tag")
                        .value_name("tags")
                        .num_args(1..)
                        .action(ArgAction::Append)
                        .help("Set which tags the script belongs to."),
                )
                .arg(Arg::new("command").help("The command/script content to be executed.")),
        )
        .subcommand(
            Command::new("config-init")
                .alias("init")
                .about("alias: init - Add a config file."),
        )
        .subcommand(
            Command::new("copy")
                .alias("cp")
                .about("alias: cp - Copy existing alias to the new one")
                .arg(Arg::new("from-alias").required(true))
                .arg(Arg::new("to-alias").required(true)),
        )
        .subcommand(
            Command::new("edit")
                .about("Edit a script matching alias.")
                .arg(Arg::new("alias").required(true)),
        )
        .subcommand(
            Command::new("list")
                .alias("ls")
                .about("alias: ls - List scripts")
                .arg(
                    Arg::new("cmd_full")
                        .short('l')
                        .long("cmd_full")
                        .action(ArgAction::SetTrue)
                        .help("Display the full command."),
                )
                .arg(
                    Arg::new("list_aliases")
                        .short('q')
                        .long("list_aliases")
                        .action(ArgAction::SetTrue)
                        .help("Only displays aliases of the scripts."),
                )
                .arg(
                    Arg::new("cmd_width")
                        .short('c')
                        .long("cmd_width")
                        .value_name("cmd-width")
                        .value_parser(clap::value_parser!(usize))
                        .help("The max number of characters to display from the command."),
                )
                .arg(
                    Arg::new("tag")
                        .short('t')
                        .long("tag")
                        .value_name("tags")
                        .num_args(1..)
                        .action(ArgAction::Append)
                        .help("Filter based on tags."),
                ),
        )
        .subcommand(
            Command::new("move")
                .alias("mv")
                .alias("rename")
                .about("alias: mv, rename - Move/rename existing alias to the new one")
                .arg(
                    Arg::new("force")
                        .short('f')
                        .long("force")
                        .action(ArgAction::SetTrue)
                        .help("Allows to overwrite the existing script"),
                )
                .arg(Arg::new("from-alias").required(true))
                .arg(Arg::new("to-alias").required(true)),
        )
        .subcommand(
            Command::new("remove")
                .alias("rm")
                .about("alias: rm - Remove a script matching alias.")
                .arg(Arg::new("alias").required(true)),
        )
        .subcommand(
            Command::new("run")
                .about("Run a script matching alias.")
                .arg(Arg::new("alias").required(true))
                .arg(Arg::new("args").num_args(0..)),
        )
        .subcommand(
            Command::new("show")
                .about("Show a script matching alias.")
                .arg(Arg::new("alias").required(true)),
        )
}

fn run_app() -> Result<i32, String> {
    let matches = match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            let use_stderr = e.use_stderr();
            let _ = e.print();
            return Ok(if use_stderr { 1 } else { 0 });
        }
    };

    let custom_config_path = matches.get_one::<String>("config-file").map(PathBuf::from);
    let verbose = matches.get_flag("verbose");

    if let Some((subcmd, sub_m)) = matches.subcommand() {
        if subcmd == "config-init" {
            let path = get_init_config_path(custom_config_path.as_deref());
            if path.exists() {
                return Err(format!(
                    "Cannot initialize config at {}, file already exists.",
                    path.display()
                ));
            }

            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() && !parent.exists() {
                    if let Err(e) = fs::create_dir_all(parent) {
                        return Err(format!("Failed to create directory. {}", e));
                    }
                }
            }

            let mut scripts = BTreeMap::new();
            scripts.insert(
                "hello-pier".to_string(),
                Script {
                    command: "echo Hello, Pier!".to_string(),
                    description: Some("This is an example command.".to_string()),
                    tags: None,
                },
            );

            let config = Config {
                scripts,
                default: DefaultConfig::default(),
            };

            save_config(&path, &config)?;
            println!("Added hello-pier");
            return Ok(0);
        }

        let config_path = get_config_path(custom_config_path.as_deref())?;
        let mut config = load_config(&config_path)?;

        match subcmd {
            "add" => {
                let alias = sub_m.get_one::<String>("alias").unwrap();
                let force = sub_m.get_flag("force");

                if config.scripts.contains_key(alias) && !force {
                    return Err(format!("AliasAlreadyExists:  {}", alias));
                }

                let command = if let Some(cmd) = sub_m.get_one::<String>("command") {
                    cmd.clone()
                } else {
                    edit_command_in_editor("")?
                };

                let description = sub_m.get_one::<String>("description").cloned();
                let tags = sub_m
                    .get_many::<String>("tag")
                    .map(|t| t.cloned().collect::<Vec<_>>());

                config.scripts.insert(
                    alias.clone(),
                    Script {
                        command,
                        description,
                        tags,
                    },
                );

                save_config(&config_path, &config)?;
                println!("Added {}", alias);
                Ok(0)
            }
            "copy" => {
                let from_alias = sub_m.get_one::<String>("from-alias").unwrap();
                let to_alias = sub_m.get_one::<String>("to-alias").unwrap();

                if !config.scripts.contains_key(from_alias) {
                    return Err(format!(
                        "AliasNotFound: No script found by alias {}",
                        from_alias
                    ));
                }

                if config.scripts.contains_key(to_alias) {
                    return Err(format!("AliasAlreadyExists:  {}", to_alias));
                }

                let script = config.scripts.get(from_alias).unwrap().clone();
                config.scripts.insert(to_alias.clone(), script);

                save_config(&config_path, &config)?;
                println!("Copy from alias {} to new alias {}", from_alias, to_alias);
                Ok(0)
            }
            "move" => {
                let from_alias = sub_m.get_one::<String>("from-alias").unwrap();
                let to_alias = sub_m.get_one::<String>("to-alias").unwrap();
                let force = sub_m.get_flag("force");

                if !config.scripts.contains_key(from_alias) {
                    return Err(format!(
                        "AliasNotFound: No script found by alias {}",
                        from_alias
                    ));
                }

                if config.scripts.contains_key(to_alias) && !force {
                    return Err(format!("AliasAlreadyExists:  {}", to_alias));
                }

                let script = config.scripts.remove(from_alias).unwrap();
                config.scripts.insert(to_alias.clone(), script);

                save_config(&config_path, &config)?;
                println!("Move from alias {} to new alias {}", from_alias, to_alias);
                Ok(0)
            }
            "remove" => {
                if config.scripts.is_empty() {
                    return Err("No scripts exist. Would you like to add a new script?".to_string());
                }

                let alias = sub_m.get_one::<String>("alias").unwrap();

                if !config.scripts.contains_key(alias) {
                    return Err(format!("AliasNotFound: No script found by alias {}", alias));
                }

                config.scripts.remove(alias);
                save_config(&config_path, &config)?;
                println!("Removed {}", alias);
                Ok(0)
            }
            "show" => {
                if config.scripts.is_empty() {
                    return Err("No scripts exist. Would you like to add a new script?".to_string());
                }

                let alias = sub_m.get_one::<String>("alias").unwrap();

                let script = config
                    .scripts
                    .get(alias)
                    .ok_or_else(|| format!("AliasNotFound: No script found by alias {}", alias))?;

                println!("{}", script.command);
                Ok(0)
            }
            "edit" => {
                if config.scripts.is_empty() {
                    return Err("No scripts exist. Would you like to add a new script?".to_string());
                }

                let alias = sub_m.get_one::<String>("alias").unwrap();

                let script = config
                    .scripts
                    .get(alias)
                    .ok_or_else(|| format!("AliasNotFound: No script found by alias {}", alias))?;

                let new_cmd = edit_command_in_editor(&script.command)?;

                if let Some(s) = config.scripts.get_mut(alias) {
                    s.command = new_cmd;
                }

                save_config(&config_path, &config)?;
                println!("Edited {}", alias);
                Ok(0)
            }
            "list" => {
                if config.scripts.is_empty() {
                    return Err("No scripts exist. Would you like to add a new script?".to_string());
                }

                let cmd_full = sub_m.get_flag("cmd_full");
                let list_aliases = sub_m.get_flag("list_aliases");
                let cmd_width = sub_m.get_one::<usize>("cmd_width").copied();
                let filter_tags: Option<Vec<String>> = sub_m
                    .get_many::<String>("tag")
                    .map(|t| t.cloned().collect());

                let mut matched_rows = Vec::new();

                if let Some(tags) = filter_tags {
                    for script_alias in config.scripts.keys() {
                        let script = &config.scripts[script_alias];
                        if let Some(script_tags) = &script.tags {
                            for tag in script_tags {
                                if tags.contains(tag) {
                                    matched_rows.push((script_alias.clone(), script.clone()));
                                }
                            }
                        }
                    }
                } else {
                    for (alias, script) in &config.scripts {
                        matched_rows.push((alias.clone(), script.clone()));
                    }
                }

                if list_aliases {
                    for (alias, _) in &matched_rows {
                        println!("{}", alias);
                    }
                } else {
                    print_table(
                        &matched_rows,
                        cmd_full,
                        cmd_width,
                        config.default.command_width,
                    );
                }

                Ok(0)
            }
            "run" => {
                if config.scripts.is_empty() {
                    return Err("No scripts exist. Would you like to add a new script?".to_string());
                }

                let alias = sub_m.get_one::<String>("alias").unwrap();

                let script = config
                    .scripts
                    .get(alias)
                    .ok_or_else(|| format!("AliasNotFound: No script found by alias {}", alias))?
                    .clone();

                let args: Vec<String> = sub_m
                    .get_many::<String>("args")
                    .map(|a| a.cloned().collect())
                    .unwrap_or_default();

                if verbose {
                    println!("Starting script \"{}\"", alias);
                    println!("-------------------------");
                }

                let status = std::process::Command::new("sh")
                    .arg("-c")
                    .arg(&script.command)
                    .arg(alias)
                    .args(&args)
                    .status();

                if verbose {
                    println!("-------------------------");
                    println!("Script complete");
                }

                let code = match status {
                    Ok(s) => s.code().unwrap_or(0),
                    Err(_) => 1,
                };

                Ok(code)
            }
            _ => Err("Unknown subcommand".to_string()),
        }
    } else if let Some(alias) = matches.get_one::<String>("alias") {
        let config_path = get_config_path(custom_config_path.as_deref())?;
        let config = load_config(&config_path)?;

        if config.scripts.is_empty() {
            return Err("No scripts exist. Would you like to add a new script?".to_string());
        }

        let script = config
            .scripts
            .get(alias)
            .ok_or_else(|| format!("AliasNotFound: No script found by alias {}", alias))?
            .clone();

        let args: Vec<String> = matches
            .get_many::<String>("args")
            .map(|a| a.cloned().collect())
            .unwrap_or_default();

        if verbose {
            println!("Starting script \"{}\"", alias);
            println!("-------------------------");
        }

        let status = std::process::Command::new("sh")
            .arg("-c")
            .arg(&script.command)
            .arg(alias)
            .args(&args)
            .status();

        if verbose {
            println!("-------------------------");
            println!("Script complete");
        }

        let code = match status {
            Ok(s) => s.code().unwrap_or(0),
            Err(_) => 1,
        };

        Ok(code)
    } else {
        Err("No subcommand provided".to_string())
    }
}

fn main() -> ExitCode {
    match run_app() {
        Ok(code) => ExitCode::from(code as u8),
        Err(err) => {
            eprintln!("error: {}", err);
            ExitCode::from(1)
        }
    }
}
