fn load_config(path: &Path) -> Result<Config, String> {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(e) => {
            return Err(format!(
                "Unable to read config from file {}: {} ",
                path.display(),
                e
            ));
        }
    };

    match toml::from_str::<Config>(&content) {
        Ok(cfg) => Ok(cfg),
        Err(e) => Err(format!(
            "Unable to parse toml config from file {}: {}",
            path.display(),
            e
        )),
    }
}

fn save_config(path: &Path, config: &Config) -> Result<(), String> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() && !parent.exists() {
            if let Err(e) = fs::create_dir_all(parent) {
                return Err(format!("Failed to create directory. {}", e));
            }
        }
    }
    let content = match toml::to_string_pretty(config) {
        Ok(c) => c,
        Err(e) => return Err(e.to_string()),
    };

    if let Err(e) = fs::write(path, content) {
        return Err(format!("Failed to write config file {}: {}", path.display(), e));
    }
    Ok(())
}

fn edit_command_in_editor(initial_content: &str) -> Result<String, String> {
    let editor = std::env::var("VISUAL")
        .or_else(|_| std::env::var("EDITOR"))
        .unwrap_or_default();

    if editor.trim().is_empty() {
        return Err(
            "EditorError: Failed when trying to get input from editor Failed to open `` as a text editor or editor was terminated with errors.".to_string()
        );
    }

    let mut temp_file = tempfile::NamedTempFile::new().map_err(|e| e.to_string())?;
    use std::io::Write;
    temp_file
        .write_all(initial_content.as_bytes())
        .map_err(|e| e.to_string())?;

    let path = temp_file.path().to_path_buf();

    let status = std::process::Command::new(&editor)
        .arg(&path)
        .status()
        .map_err(|_| {
            format!(
                "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
                editor
            )
        })?;

    if !status.success() {
        return Err(format!(
            "EditorError: Failed when trying to get input from editor Failed to open `{}` as a text editor or editor was terminated with errors.",
            editor
        ));
    }

    let content = fs::read_to_string(&path).map_err(|e| e.to_string())?;
    Ok(content.trim_end_matches('\r').trim_end_matches('\n').to_string())
}

fn print_table(
    rows: &[(String, Script)],
    cmd_full: bool,
    cmd_width: Option<usize>,
    default_cmd_width: Option<usize>,
) {
    let mut alias_max = "Alias".len();
    let mut tags_max = "Tags".len();
    let mut cmd_max = "Command".len();
    let mut desc_max = "Description".len();

    let mut processed_rows = Vec::new();

    for (alias, script) in rows {
        let tags_str = match &script.tags {
            Some(t) if !t.is_empty() => t.join(","),
            _ => String::new(),
        };

        let raw_cmd = &script.command;
        let mut cmd_str = raw_cmd.clone();

        if !cmd_full {
            let width_limit = cmd_width.or(default_cmd_width).unwrap_or(80);
            if cmd_str.chars().count() > width_limit {
                cmd_str = cmd_str.chars().take(width_limit).collect();
            }
        }

        let desc_str = script.description.as_deref().unwrap_or("");

        alias_max = alias_max.max(alias.len());
        tags_max = tags_max.max(tags_str.len());
        cmd_max = cmd_max.max(cmd_str.len());
        desc_max = desc_max.max(desc_str.len());

        processed_rows.push((alias.clone(), tags_str, cmd_str, desc_str.to_string()));
    }

    let total_width = alias_max + tags_max + cmd_max + desc_max + 13;
    let border = "≖".repeat(total_width);

    println!("{}", border);
    println!(
        "⋮ {:<a_w$} ⋮ {:<t_w$} ⋮ {:<c_w$} ⋮ {:<d_w$} ⋮",
        "Alias",
        "Tags",
        "Command",
        "Description",
        a_w = alias_max,
        t_w = tags_max,
        c_w = cmd_max,
        d_w = desc_max
    );
    println!("{}", border);

    for (alias, tags, cmd, desc) in processed_rows {
        println!(
            "⋮ {:<a_w$} ⋮ {:<t_w$} ⋮ {:<c_w$} ⋮ {:<d_w$} ⋮",
            alias,
            tags,
            cmd,
            desc,
            a_w = alias_max,
            t_w = tags_max,
            c_w = cmd_max,
            d_w = desc_max
        );
    }
    println!("{}", border);
}

